fn simulate_flips(count: Int) -> Int {
  let mut heads = 0;
  let mut seed = 1;
  let mut i = 0;
  while i < count {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    if seed % 2 == 0 { heads += 1; };
    i += 1;
  };
  heads
}

fn main() -> Int {
  let h10 = simulate_flips(10);
  io.println(h10);
  io.println(h10 * 100 / 10);

  let h100 = simulate_flips(100);
  io.println(h100);
  io.println(h100 * 100 / 100);

  let h1000 = simulate_flips(1000);
  io.println(h1000);
  io.println(h1000 * 100 / 1000);
  return 0;
}
